begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into auth.users(id) values ('00000000-0000-0000-0000-000000000011'),('00000000-0000-0000-0000-000000000012');
insert into public.parties(id,code,title,host_id) values('10000000-0000-0000-0000-000000000011','V2CART11','cart test','00000000-0000-0000-0000-000000000011');
set local role service_role;
insert into public.party_agent_workspaces(party_id,workspace,input_revision,draft_revision) values('10000000-0000-0000-0000-000000000011','{}',0,1);
insert into public.party_agent_drafts(party_id,draft_revision,input_revision,ready,projection) values('10000000-0000-0000-0000-000000000011',1,0,true,'{"schemaVersion":2,"partyId":"10000000-0000-0000-0000-000000000011","ready":true,"inputRevision":0,"draftRevision":1,"lines":[],"totalCents":0,"unresolvedCount":0,"blockerCodes":[]}');
update public.party_agent_workspaces set checkpoint='{"commerce":{"inputRevision":0,"draftRevision":1,"cart":{"cartId":"cart"}}}';
create temporary table operations as select public.agent_v2_approve('10000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000011',1,'one') as id;
select extensions.is((select approved_commerce->'cart'->>'cartId' from public.party_cart_operations where id=(select id from operations)),'cart','approval captures private commerce context');
update public.party_agent_workspaces set checkpoint='{"commerce":{"cart":{"cartId":"new-cart"}}}';
select extensions.is((select approved_commerce->'cart'->>'cartId' from public.party_cart_operations where id=(select id from operations)),'cart','later drafts do not alter approved commerce');
select extensions.throws_ok($$update public.party_cart_operations set approved_commerce='{}' where id=(select id from operations)$$,'P0001','Approved commerce is immutable','commerce evidence cannot be replaced');
select extensions.throws_ok($$select public.agent_v2_cart_acquire((select id from operations),'00000000-0000-0000-0000-000000000012','worker','cart')$$,'P0001','Host authority required','member cannot acquire cart');
update public.party_agent_workspaces set source_revision=1;
select extensions.throws_ok($$select public.agent_v2_cart_acquire((select id from operations),'00000000-0000-0000-0000-000000000011','worker','cart')$$,'P0001','Pending source events','arrival after approval fences acquire');
update public.party_agent_workspaces set processed_source_revision=1,input_revision=1;
select extensions.throws_ok($$select public.agent_v2_cart_acquire((select id from operations),'00000000-0000-0000-0000-000000000011','worker','cart')$$,'P0001','Exact current ready draft required','stale approval blocked');
update public.party_agent_workspaces set input_revision=0;
select extensions.lives_ok($$select public.agent_v2_cart_acquire((select id from operations),'00000000-0000-0000-0000-000000000011','worker','cart')$$,'host acquires writer');
select extensions.is((select code from public.party_agent_activity where party_id='10000000-0000-0000-0000-000000000011' order by id desc limit 1),'cart_applying','cart writer state is projected safely');
select extensions.throws_ok($$select public.agent_v2_cart_acquire((select id from operations),'00000000-0000-0000-0000-000000000011','worker','cart')$$,'P0001','Cart operation already acquired','same worker cannot acquire twice');
create temporary table second_operation as select public.agent_v2_approve('10000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000011',1,'two') as id;
select extensions.throws_ok($$select public.agent_v2_cart_acquire((select id from second_operation),'00000000-0000-0000-0000-000000000011','worker2','cart2')$$,'P0001','Cart writer already active','one active writer for party even another cart');
select extensions.throws_ok($$select public.agent_v2_cart_prepare((select id from operations),'wrong','{}','{}','[]')$$,'P0001','Cart writer required','other worker cannot prepare');
select extensions.throws_ok($$select public.agent_v2_cart_prepare((select id from operations),'worker','{"cartId":"cart"}','{"snapshot":{"cartId":"cart"},"managed":[]}','[]')$$,'P0001','Conditional cartVersion required','cart plan without version is rejected');
select public.agent_v2_cart_prepare((select id from operations),'worker','{"cartId":"cart","cartVersion":"v1"}','{"snapshot":{"cartId":"cart","cartVersion":"v1"},"managed":[]}','[]');
select extensions.throws_ok($$select public.agent_v2_cart_prepare((select id from operations),'worker','{}','{}','[]')$$,'P0001','Cart plan is immutable','prepared intended writes immutable');
update public.party_agent_workspaces set source_revision=2;
select public.agent_v2_cart_finish((select id from operations),'worker','unknown',null,'timeout');
select extensions.is((select status from public.party_cart_operations where id=(select id from operations)),'unknown','ambiguous state persisted');
update public.party_agent_workspaces set processed_source_revision=2;
select extensions.throws_ok($$select public.agent_v2_cart_acquire((select id from second_operation),'00000000-0000-0000-0000-000000000011','worker2','cart')$$,'P0001','Cart writer already active','unknown retains writer lock');
select public.agent_v2_cart_finish((select id from operations),'worker','verified','{"cartId":"cart","cartVersion":"v2"}',null);
select extensions.is((select readback->>'cartId' from public.party_cart_operations where id=(select id from operations)),'cart','readback persisted');
select extensions.is((select code from public.party_agent_activity where party_id='10000000-0000-0000-0000-000000000011' order by id desc limit 1),'cart_applied','verified cart state is projected safely');
select extensions.lives_ok($$select public.agent_v2_cart_acquire((select id from operations),'00000000-0000-0000-0000-000000000011','worker3','cart')$$,'verified duplicate returns without writer');
select extensions.ok(not has_function_privilege('authenticated','public.agent_v2_cart_acquire(uuid,uuid,text,text)','execute'),'authority RPC is service-only');
select * from extensions.finish();
rollback;
